/* Shared demonstration fixtures. Production model/authentication/storage services are not connected. */
const demoAccount={name:'Farmer Gigremosa',email:'farmer@example.com',plan:'Free'};
const supportedAbnormalities=['Red spots or hemorrhagic discoloration','Skin lesions or ulcers','Fin deterioration','Scale loss','Cloudy eyes'];
const demoRecords=[
 {id:'IS-1104',date:'Nov 4, 2026 · 08:42',source:'Camera',findings:[supportedAbnormalities[0]],sync:'Pending synchronization',synced:false},
 {id:'IS-1102',date:'Nov 2, 2026 · 09:15',source:'Gallery',findings:[supportedAbnormalities[0]],sync:'Synchronized',synced:true},
 {id:'IS-1028',date:'Oct 28, 2026 · 07:30',source:'Camera',findings:[supportedAbnormalities[0]],sync:'Synchronized',synced:true}
];
const limitation='Preliminary visual screening only. These findings do not confirm vibriosis or establish a diagnosis.';
function demoBadge(){return '<span class="chip demo-chip">DEMONSTRATION DATA</span>';}
function previewPlan(){return state.planPreview==='pro'?'pro':'free';}
function synchronizedRecords(){return demoRecords.filter(r=>r.synced);}
function planRecords(){const records=synchronizedRecords();return previewPlan()==='pro'?records:records.slice(0,1);}
function planPreviewSelector(){const plan=previewPlan();return `<section class="plan-preview-control"><div><span class="eyebrow">Monitoring demonstration</span><p>Preview states change prototype access only. They do not activate a subscription.</p></div><div class="plan-segmented" role="group" aria-label="Demonstration plan preview"><button data-plan-preview="free" aria-pressed="${plan==='free'}">Free Preview</button><button data-plan-preview="pro" aria-pressed="${plan==='pro'}">Pro Preview</button></div></section>`;}
function planBenefits(kind){return kind==='free'?['Core Bangus image scanning','Preliminary risk advisories','General care and biosecurity guidance','Offline scanning and local history','Basic online monitoring','Standard cloud record capacity']:['All Free Plan capabilities','Higher cloud record capacity','Extended online scan history','Expanded historical summaries and trend views'];}
function planList(kind){return `<ul class="plan-benefit-list">${planBenefits(kind).map(item=>`<li>${item}</li>`).join('')}</ul>`;}
function scanPhoto(){return `<figure class="scan-photo"><img src="${new URL('assets/bangus-demo-observation.png',assetBase).href}" alt="Synthetic Bangus example with a small cluster of red spots on its flank"/><figcaption>Synthetic demonstration image · Example observation only</figcaption></figure>`;}
function assessment(r){return r.findings.length?'Visible abnormalities observed. Further assessment is advised.':'No supported visible abnormalities recognized in this example. This does not establish that the fish is disease-free.';}
function currentRecord(){return demoRecords.find(r=>r.id===state.recordId)||demoRecords[1];}
function resultFields(r){return `<div class="finding-label">Visible abnormality</div>${r.findings.map(f=>`<div class="finding-item"><span class="finding-dot"></span>${f}</div>`).join('')||'<p class="muted">No supported abnormality recognized.</p>'}<p class="advisory">${assessment(r)}</p>`;}
function localPage(name,content,back='dashboard',active='dashboard'){return `<div class="m-page">${mHead()}<div class="m-main">${title(name,back)}${content}</div>${mNav(active)}</div>`;}
function identityFields(edit=false){return `<div class="form-field"><label for="farmer-name">Full name</label><input id="farmer-name" data-profile-name value="${edit?escapeText(demoAccount.name):''}" placeholder="Your full name" autocomplete="name"/></div><div class="form-field"><label for="farmer-email">Email address</label><input id="farmer-email" type="email" data-profile-email value="${edit?escapeText(demoAccount.email):''}" placeholder="farmer@example.com" autocomplete="email"/></div>`;}
function escapeText(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function recordButton(r,platform='android'){return `<button class="record record-button" data-record="${r.id}" data-record-platform="${platform}"><img class="record-thumb" src="${new URL('assets/bangus-demo-observation.png',assetBase).href}" alt=""/><span><b>Visible abnormalities observed</b><small>${r.date}</small><small>Red spots · ${r.id}</small></span><span class="right tag ${r.synced?'synced':'pending'}">${r.synced?'Synchronized':'Pending sync'}</span></button>`;}
function alignedMobile(name){
 if(name==='starter')return `<div class="m-page starter-page">${mHead()}<div class="m-main"><span class="eyebrow">Bangus farm companion</span><h1>Small signs.<br/>Better-informed care.</h1><p class="muted">Observe visible changes in your Bangus with preliminary image screening.</p><div class="starter-fish"><img src="${fish}" alt="Bangus illustration"/><span class="fish-orbit orbit-one"></span><span class="fish-orbit orbit-two"></span></div><div class="welcome-card"><span class="chip">Android edge-AI workflow</span><h3 style="margin-top:10px">From observation to action.</h3><p class="muted">Scan, review general guidance, and keep monitoring records together.</p></div>${button('Get started →','m:login','wide-button')}<p class="form-note">${limitation}</p></div></div>`;
 if(name==='login')return `<div class="m-page auth-page">${mHead('starter')}<div class="m-main"><div class="auth-emblem">⌁</div>${title('Welcome back','starter')}<p class="muted">One farmer account. Your Android and web records.</p><div class="form-field"><label for="login-email">Email address</label><input id="login-email" type="email" value="${escapeText(demoAccount.email)}"/></div><div class="form-field"><label for="login-password">Password</label><input id="login-password" type="password" placeholder="Enter password"/></div>${button('Preview sign-in','m:dashboard','wide-button')}${button('Create a farmer account','m:register','secondary wide-button')}<p class="form-note">Initial sign-in requires internet. A previously authenticated farmer may use supported offline functions while the retained session remains valid. Authentication is a prototype.</p></div></div>`;
 if(name==='register')return `<div class="m-page auth-page">${mHead('login')}<div class="m-main">${title('Create your account','login')}<p class="muted">Begin with the proposed Free Plan and core monitoring tools.</p>${identityFields()}<div class="form-field"><label for="register-password">Password</label><input id="register-password" type="password" placeholder="Create password"/></div>${button('Preview registration','m:dashboard','wide-button')}<p class="form-note">Internet is required for registration. This demonstration does not create an account. The same account is intended for Android and web.</p></div></div>`;
 if(name==='dashboard')return localPage('Your farm companion',`<span class="eyebrow">Hello, ${escapeText(demoAccount.name)}</span><div class="dashboard-highlight"><div><span class="chip">Free Plan</span><h2>Notice changes.<br/>Keep a clearer record.</h2><p>Begin your next Bangus visual check.</p></div><img src="${fish}" alt="Bangus illustration"/></div><div class="quick-grid">${[['sample','◌','Inspection sample','Optional guide'],['capture','⌁','Scan Bangus','Camera or gallery'],['guidance','✦','Care guidance','General biosecurity'],['history','◷','Scan history','Your saved observations']].map(([key,ic,label,sub])=>`<button class="quick" data-mobile="${key}"><span class="quick-icon">${ic}</span><b>${label}</b><small>${sub}</small></button>`).join('')}</div><div class="section-heading"><h3>Local monitoring</h3>${demoBadge()}</div><div class="stat-grid"><div class="stat"><strong>${demoRecords.length}</strong><span>Saved example scans</span></div><div class="stat"><strong>${demoRecords.filter(r=>!r.synced).length}</strong><span>Pending example sync</span></div></div>`,'','dashboard');
 if(name==='sample')return localPage('Inspection sample',`<span class="chip">Optional step</span><p class="muted" style="margin-top:12px">Organize your visual inspection before capturing an image.</p><div class="form-field"><label for="population">Estimated Bangus population</label><input id="population" type="number" min="1" placeholder="Enter population estimate"/></div><div class="notice"><span class="eyebrow">Prototype placeholder</span><h3 style="margin-top:8px">Sampling rules awaiting approval</h3><p class="muted">A numerical recommendation will appear here after the sampling method is approved. No formula or confidence level is assumed.</p></div>${button('Skip sampling & capture →','m:capture','wide-button')}<p class="form-note">You can always scan without a sampling recommendation.</p>`);
 if(name==='capture')return localPage('Capture Bangus image',`${demoBadge()}<p class="muted" style="margin-top:12px">Keep the full fish in frame with even lighting.</p><div class="camera-stage"><img src="${fish}" alt="Bangus framing illustration"/><span class="camera-corner tl"></span><span class="camera-corner tr"></span><span class="camera-corner bl"></span><span class="camera-corner br"></span><span class="camera-hint">Position Bangus within the frame</span></div><div class="button-row" style="margin-top:14px"><button class="primary" data-source="Camera">Camera</button><button class="secondary" data-source="Gallery">Gallery</button></div><div class="notice" style="margin-top:14px"><h3>For a clearer image</h3><p class="muted">Avoid blur, heavy reflections, and obstructed body areas. Camera and image selection are demonstration controls.</p></div>`,'dashboard','capture');
 if(name==='quality'){const rejected=state.qualityRejected;return localPage('Image quality & analysis',`${demoBadge()}<div class="quality-box" style="margin-top:14px"><div class="quality-icon">${rejected?'!':'✓'}</div><h3>${rejected?'Image rejected: too blurred':'Accepted image example'}</h3><p class="muted">${rejected?'Fish details cannot be assessed clearly. Replace this image to continue. It will not enter completed scan history.':'The example image is clear and framed for assessment. Continue to preview the on-device analysis result.'}</p></div><div class="demo-state-controls"><button data-quality="accepted" aria-pressed="${!rejected}">Accepted example</button><button data-quality="rejected" aria-pressed="${!!rejected}">Rejected example</button></div>${rejected?button('Replace image','m:capture','wide-button'):`<div class="notice" style="margin-top:12px"><h3>On-device YOLOv8n</h3><p class="muted">Inference is represented by a demonstration result. No model is connected.</p></div>${button('Preview analysis result','m:result','wide-button')}`}`,'capture','capture');}
 if(name==='result')return localPage('Preliminary scan result',`${demoBadge()}${scanPhoto()}${resultFields(demoRecords[0])}<p class="warning">${limitation}</p><p class="form-note">Synthetic example, not a real AI prediction. Record storage is automatic in the intended workflow.</p>${button('Care & biosecurity guidance','m:guidance','wide-button')}${button('View scan history','m:history','secondary wide-button')}`,'quality','capture');
 if(name==='history')return localPage('Scan history',`${demoBadge()}<p class="muted" style="margin-top:10px">Completed scans save locally. Pending records synchronize automatically when connectivity returns.</p><div class="card">${demoRecords.map(r=>recordButton(r)).join('')}</div><p class="form-note">Example completed scans only. Rejected images are excluded.</p>`,'dashboard','history');
 if(name==='details'){const r=currentRecord();return localPage('Scan details',`${demoBadge()}${scanPhoto()}<div class="record-metadata"><b>${r.id}</b><span>${r.date}</span><span>Source: ${r.source}</span><span>Stored locally · ${r.sync}</span></div>${resultFields(r)}<p class="warning">${limitation}</p>`,'history','history');}
 if(name==='profile')return localPage('Profile',`${demoBadge()}<div class="profile-head"><div class="avatar">FG</div><h2>${escapeText(demoAccount.name)}</h2><p class="muted">${escapeText(demoAccount.email)}</p><span class="chip free">Free Plan</span></div><div class="plan-card"><span class="eyebrow" style="color:#bcf5e9">Your account plan</span><h2 style="margin-top:8px">Room to grow.</h2><p>Explore the proposed Free and Pro structure. Core screening tools remain accessible.</p><button class="secondary" data-mobile="plans">Plan information →</button></div><button class="profile-row record-button" data-mobile="edit"><b>Edit profile</b><span class="right">→</span></button><button class="profile-row record-button" data-mobile="pro-status"><b>Subscription status</b><span class="right">→</span></button><button class="profile-row record-button" data-mobile="login"><b>Log out</b><span class="right">→</span></button>`,'','profile');
 if(name==='edit')return localPage('Edit profile',`${demoBadge()}${identityFields(true)}<button class="wide-button" data-save-profile="android">Save demo changes</button><p class="form-note">Example account details are shared across this Android and web preview. Changes last for this gallery session only.</p>`,'profile','profile');
 if(name==='plans')return localPage('Plan information',`<p class="muted">Compare approved plan benefits. Subscription activation is proposed functionality and is not yet available.</p><div class="comparison plan-comparison"><section class="tier"><span class="chip free">Free Plan</span><h3>Essential screening</h3>${planList('free')}</section><section class="tier featured"><span class="chip">Pro Plan Preview</span><h3>Expanded monitoring</h3>${planList('pro')}</section></div><div class="notice compact-notice"><b>Prototype-only plan state</b><p class="muted">No price, payment provider, billing period, or activation is represented.</p></div>${button('View subscription status','m:pro-status','wide-button')}`,'profile','profile');
 if(name==='pro-status')return localPage('Subscription status',`<div class="plan-card"><span class="eyebrow" style="color:#bcf5e9">Current demonstrated state</span><h2 style="margin-top:8px">Free Plan</h2><p>Core scanning, preliminary advisories, offline history, and basic online monitoring are shown in this demonstration.</p></div><div class="card plan-status-card"><span class="chip">Pro Plan Preview</span><h3>Expanded cloud history and monitoring</h3><p class="muted">A future Pro Plan would provide higher cloud record capacity, extended online scan history, and expanded historical summaries and trends.</p></div><div class="notice compact-notice"><b>Subscription activation is not yet available.</b><p class="muted">This is a plan-benefit preview, not a completed payment or active subscription.</p></div>${button('Return to profile','m:profile','wide-button')}`,'plans','profile');
 return null;
}
function alignedWeb(name){const received=demoRecords.filter(r=>r.synced),review=received.filter(r=>r.findings.length).length;
 if(name==='login')return `<div class="web-login"><div class="web-login-intro"><span class="eyebrow">IcthyoScan · Web companion</span><h1>Your observations.<br/>A clearer overview.</h1><img src="${fish}" alt="Bangus illustration"/><p>View synchronized records from your Android application.</p></div><div class="web-login-card"><div class="web-brand"><img src="${logo}" alt=""/>IcthyoScan</div><h1 style="margin-top:24px">Welcome back</h1>${demoBadge()}<div class="form-field"><label for="web-email">Email address</label><input id="web-email" type="email" value="${escapeText(demoAccount.email)}"/></div><div class="form-field"><label for="web-password">Password</label><input id="web-password" type="password" placeholder="Enter password"/></div>${button('Preview sign-in →','w:dashboard','wide-button')}<p class="form-note">Internet required. Use the same farmer account as Android. Authentication is not connected.</p></div></div>`;
 if(name==='dashboard'){const records=planRecords(),plan=previewPlan(),advisories=records.filter(r=>r.findings.length).length;return webShell(`<main class="web-main"><div class="web-title"><div><span class="eyebrow">Your farm, in view</span><h1>Monitoring overview</h1><p>Successfully synchronized Bangus screening records.</p></div>${demoBadge()}</div>${planPreviewSelector()}<div class="web-banner">${plan==='pro'?'Pro Preview shows the extended demonstration history and trend view.':'Free Preview shows the basic demonstration history view.'} Local-only Android records are not visible here.</div><div class="web-stats aligned-stats"><div class="web-stat"><span>Synchronized scans</span><b>${records.length}</b></div><div class="web-stat"><span>Review advisories</span><b>${advisories}</b></div><div class="web-stat"><span>Preview state</span><b>${plan==='pro'?'Pro':'Free'}</b></div></div><div class="web-grid"><section class="web-card"><h2>${plan==='pro'?'Historical monitoring by scan date':'Basic scan activity'}</h2><p>${plan==='pro'?'Expanded demonstration summary of synchronized records.':'Demonstration summary of the available synchronized record.'}</p><div class="chart plan-chart">${records.slice().reverse().map(r=>`<div class="bar" style="height:70%"><b>1 record</b><span>${r.date.split(' · ')[0]}</span></div>`).join('')}</div>${plan==='pro'?'<p class="form-note">Date-based trend view · demonstration data only</p>':''}</section><section class="web-card web-fish-card"><img src="${fish}" alt="Bangus illustration"/><h2>${plan==='pro'?'Review a longer synchronized history.':'Keep observing. Keep informed.'}</h2><p>${plan==='pro'?'Pro Preview adds extended history, historical summaries, and trend browsing.':'Free Preview includes basic monitoring summaries and recent synchronized records.'}</p><button class="ghost-button" data-web="web-history">View received records →</button></section></div><section class="web-card" style="margin-top:22px"><h2>Recent synchronized records</h2>${records.map(r=>recordButton(r,'web')).join('')}</section></main>`,'dashboard');}
 if(name==='web-history'){const plan=previewPlan();let records=planRecords();if(plan==='pro'&&state.historyRange==='nov')records=records.filter(r=>r.date.startsWith('Nov'));if(plan==='pro'&&state.historyRange==='oct')records=records.filter(r=>r.date.startsWith('Oct'));return webShell(`<main class="web-main"><div class="web-title"><div><span class="eyebrow">Received from Android</span><h1>Web scan history</h1><p>Completed and successfully synchronized records only.</p></div>${demoBadge()}</div>${planPreviewSelector()}<div class="history-window-note">${plan==='pro'?'Pro Preview shows the extended demonstration history.':'Free Preview shows the basic demonstration history window. Older demonstration records remain available in Pro Preview.'}</div>${plan==='pro'?`<div class="history-filters" aria-label="Date-based history browsing"><span>Browse by date</span><button data-history-range="all" aria-pressed="${!state.historyRange||state.historyRange==='all'}">All dates</button><button data-history-range="nov" aria-pressed="${state.historyRange==='nov'}">November 2026</button><button data-history-range="oct" aria-pressed="${state.historyRange==='oct'}">October 2026</button></div>`:''}<section class="web-card"><table class="web-table"><thead><tr><th>Scan date</th><th>Abnormality</th><th>Preliminary assessment</th><th>Status / record</th></tr></thead><tbody>${records.map(r=>`<tr><td>${r.date}</td><td>${r.findings.join(', ')}</td><td>Further assessment advised</td><td><button class="ghost-button" data-record="${r.id}" data-record-platform="web">${r.id} · Synchronized →</button></td></tr>`).join('')}</tbody></table></section></main>`,'web-history');}
 if(name==='web-details'){const r=received.find(r=>r.id===state.recordId)||received[0];return webShell(`<main class="web-main"><div class="web-title"><div><button class="back-btn" data-web="web-history">← Scan history</button><h1 style="margin-top:15px">Web scan details</h1><p>${r.id} · ${r.date}</p></div>${demoBadge()}</div><div class="split-card"><section class="web-card">${scanPhoto()}<div class="record-metadata"><span>Image source: ${r.source}</span><span>Synchronization: ${r.sync}</span></div></section><section class="web-card">${resultFields(r)}<p class="warning">${limitation}</p><h3>General care reference</h3><p>Continue observing and documenting visible changes. Follow established farm hygiene procedures and seek qualified assistance if concerns persist.</p></section></div></main>`,'web-history');}
 if(name==='web-profile')return webShell(`<main class="web-main"><div class="web-title"><div><span class="eyebrow">One farmer account</span><h1>Profile</h1></div>${demoBadge()}</div><div class="split-card"><section class="web-card profile-head"><div class="avatar">FG</div><h2>${escapeText(demoAccount.name)}</h2><p>${escapeText(demoAccount.email)}</p><span class="chip free">Free Plan</span><p><button class="ghost-button" data-web="web-edit">Edit profile</button></p><button class="ghost-button" data-web="login">Log out</button></section><section class="plan-card"><h2>Your monitoring companion.</h2><p>Shared Android and web account. Explore the proposed Free and Pro plan information.</p><button class="secondary" data-web="web-plans">View plan information →</button></section></div></main>`,'web-profile');
 if(name==='web-edit')return webShell(`<main class="web-main"><div class="web-form"><button class="back-btn" data-web="web-profile">← Profile</button><h1 style="margin-top:20px">Edit profile</h1>${demoBadge()}${identityFields(true)}<button class="wide-button" data-save-profile="web">Save demo changes</button><p class="form-note">Updates are reflected in the Android and web previews for this gallery session.</p></div></main>`,'web-profile');
 if(name==='web-plans')return webShell(`<main class="web-main"><div class="web-title"><div><span class="eyebrow">Account plan</span><h1>Plan information</h1><p>Approved plan benefits shown as a prototype. No transaction or activation occurs here.</p></div>${demoBadge()}</div><div class="split-card web-plan-comparison"><section class="web-card"><span class="chip free">Free Plan</span><h2 style="margin-top:10px">Essential screening</h2>${planList('free')}</section><section class="web-card pro-plan-card"><span class="chip">Pro Plan Preview</span><h2 style="margin-top:10px">Expanded monitoring</h2>${planList('pro')}<div class="notice"><b>Proposed functionality</b><p class="muted">Subscription activation is not yet available. No price, payment, billing, or successful activation is shown.</p></div></section></div></main>`,'web-plans');
 return null;
}
